from decimal import Decimal, InvalidOperation, ROUND_HALF_UP


class Group:
    def __init__(self, members: list[str]) -> None:
        if len(set(members)) != len(members):
            raise ValueError("Group members must be unique")
        self._members = list(members)
        self._member_set = set(members)
        self._balances = {member: 0 for member in members}  # cents

    def add_expense(
        self,
        payer: str,
        amount: float,
        participants: list[str] | None = None,
    ) -> None:
        if payer not in self._member_set:
            raise ValueError("Payer is not a group member")

        if participants is None:
            participants = self._members

        if not participants:
            raise ValueError("An expense must have at least one participant")
        if len(set(participants)) != len(participants):
            raise ValueError("Participants must be unique")
        if any(participant not in self._member_set for participant in participants):
            raise ValueError("Participant is not a group member")

        try:
            value = Decimal(str(amount))
            if not value.is_finite() or value <= 0:
                raise ValueError("Amount must be positive and finite")
            cents = int((value * 100).quantize(Decimal("1"), rounding=ROUND_HALF_UP))
        except (InvalidOperation, TypeError) as exc:
            raise ValueError("Invalid amount") from exc

        share = cents // len(participants)
        for participant in participants:
            if participant != payer:
                self._balances[participant] -= share
                self._balances[payer] += share

    def balances(self) -> dict[str, float]:
        return {member: cents / 100 for member, cents in self._balances.items()}

    def settle_up(self) -> list[tuple[str, str, float]]:
        debtors = [
            [member, -balance]
            for member, balance in self._balances.items()
            if balance < 0
        ]
        creditors = [
            [member, balance]
            for member, balance in self._balances.items()
            if balance > 0
        ]
        debtors.sort(key=lambda entry: entry[1], reverse=True)
        creditors.sort(key=lambda entry: entry[1], reverse=True)

        payments = []
        i = j = 0
        while i < len(debtors) and j < len(creditors):
            if debtors[i][1] < 100:
                i += 1
                continue
            if creditors[j][1] < 100:
                j += 1
                continue

            cents = min(debtors[i][1], creditors[j][1])
            payments.append((debtors[i][0], creditors[j][0], cents / 100))
            debtors[i][1] -= cents
            creditors[j][1] -= cents

            if debtors[i][1] == 0:
                i += 1
            if creditors[j][1] == 0:
                j += 1

        return payments
